using System;
using System.Collections.Generic;
using GrimDynasty.TaskLogic;
using GrimDynasty.TaskAuto;
using GrimDynasty.TaskItems;
public static class ItemConditionTests {
 static int n;static void Is(bool b,string s){n++;if(!b)throw new Exception(s);}
 static ItemObject Item(string name,int amount){return new ItemObject{Kind=ItemObjectKind.Item,ObjectName=name,DataNameFromSlot590=name,PrefixFromSlot590="",SuffixFromSlot590="",CompleteByteFromSlot3F8=1,QuantityFromSlot618=amount};}
 public static int Main(){try{
  var w=ItemWorld.Empty();w.ClientPlayerId=1;w.Objects.Add(10,Item("records/a.dbr",2));w.InventoryItemIds.Add(10);Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==2,"inventory");
  w.Objects.Add(11,Item("records/a.dbr",3));w.PersonalSacks.Add(new SackSnapshot{ItemIds=new List<uint>{11}});w.Objects.Add(12,Item("records/a.dbr",5));w.TransferSacks.Add(new SackSnapshot{ItemIds=new List<uint>{12}});w.Objects.Add(13,new ItemObject{Kind=ItemObjectKind.Item,QuantityFromSlot618=7});w.ReagentIds.Add("records/a.dbr",13);Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==17,"all four sources");
  w.Objects.Add(20,new ItemObject{Kind=ItemObjectKind.ControllerCharacter,EquipmentIndexComplete=true});w.RawControllerId16C0=20;w.Objects[20].EquippedLocations.Add(10,1);Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==15,"equipped inventory item excluded");w.Objects[20].EquippedLocations[10]=0;w.Objects[20].EquippedLocations.Add(11,1);Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==17,"personal sack ignores character equipment filter");
  w.Objects[10].PrefixFromSlot590="prefix";Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==15,"nonempty prefix fails empty qualifier query");w.Objects[10].PrefixFromSlot590="";w.Objects[10].SuffixFromSlot590="suffix";Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==15,"nonempty suffix");w.Objects[10].SuffixFromSlot590="";
  w.Objects[10].CompleteByteFromSlot3F8=0;Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==15,"complete flag filters inventory");Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",false).Count==17,"flag false allows incomplete");w.Objects[10].CompleteByteFromSlot3F8=1;
  w.AsciiCLocaleKnown=true;Is(ItemCountQuery.CountForHasItem(w,"RECORDS/A.DBR",true).Count==10,"inventory case fold, reagent exact key");Is(ItemCountQuery.CountForHasItem(w,"records\\a.dbr",true).Count==10,"inventory slash fold, reagent slash exact");w.AsciiCLocaleKnown=false;Is(ItemCountQuery.CountForHasItem(w,"RECORDS/A.DBR",true).Status=="Unsupported","unknown locale");Is(ItemCountQuery.CountForHasItem(w,"records/*.dbr",true).Count==0,"no guessed wildcard semantics");
  var transfer=w.TransferSacks;w.TransferSacks=null;Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Status=="Unsupported","all sources required, no threshold shortcircuit");w.TransferSacks=transfer;
  var ctl=w.Objects[20];ctl.EquipmentIndexComplete=false;ctl.EquippedLocations.Remove(10);Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Status=="Unsupported","unknown equipment location");ctl.EquipmentIndexComplete=true;w.RawControllerId16C0=999;Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==17,"known absent controller does not exclude");w.ObjectIndexComplete=false;Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Status=="Unsupported","unknown controller not absence");w.ObjectIndexComplete=true;
  w=ItemWorld.Empty();w.ClientPlayerId=1;w.Objects.Add(10,Item("records/a.dbr",2));w.InventoryItemIds.Add(10);var bus=new OfflineEvents(true){DebugEnabled=false};var player=new World{MainPlayerResolved=true};HasItemCondition c;
  HasItemCondition.Create(1,3,2,true,"records/a.dbr",bus,w,out c);Is(c.Evaluate(player).Value==true,"predicate count");Is(c.Start().Status=="Known"&&c.Owner16Attached&&c.Owner17Attached,"two callbacks attached");Is(c.Start().Changed==false,"identity dedup both routes");
  var body=new ItemEventBody{PlayerId=2,ItemObjectId=999};Is(c.Receive(body,16).Changed==false,"wrong player rejects before item lookup");body.PlayerId=1;body.ItemObjectId=10;w.AsciiCLocaleKnown=true;w.Objects[10].ObjectName="RECORDS\\A.DBR";Is(c.Receive(body,16).Changed==false,"event does not fold slashes");w.Objects[10].ObjectName="RECORDS/A.DBR\0tail";Is(c.Receive(body,16).Status=="Known"&&c.ChangedByte14==1&&c.TextByte15==1,"event C string case comparison");
  Is(w.Objects[10].QuantityFromSlot618==2,"event does not mutate inventory quantity");Is(c.Reset().Changed==false&&c.ChangedByte14==1&&c.TextByte15==1&&c.Evaluate(player).Value==true,"reset no-op preserves flags and stock");c.PureLocalizationContextKnown=true;c.SystemTimeSnapshot=4000;Is(c.CheckOnChangedNoDisplay().Status=="Known","closed display gate");c.SystemTimeSnapshot=4001;Is(c.CheckOnChangedNoDisplay().Status=="Unsupported","visible display unimplemented");
  Is(c.End().Status=="Known"&&!c.Owner16Attached&&!c.Owner17Attached,"both owners detached");Is(bus.Send(new QuestEvent{Body=body},16).Delivered==0&&bus.Send(new QuestEvent{Body=body},17).Delivered==0,"both routes unsubscribed");
  for(int i=0;i<6;i++){HasItemCondition cmp;HasItemCondition.Create(1,i,3,true,"records/a.dbr",bus,w,out cmp);Is(cmp.Evaluate(player).Value==new[]{true,true,false,false,false,true}[i],"signed comparison "+i);}
  w.Objects[10].CompleteByteFromSlot3F8=0;HasItemCondition v0,v1;HasItemCondition.Create(0,3,1,false,"records/a.dbr",bus,w,out v0);HasItemCondition.Create(1,3,1,false,"records/a.dbr",bus,w,out v1);Is(v0.Evaluate(player).Value==false&&v1.Evaluate(player).Value==true,"v0 default flag true, v1 supplied false");
  w.Objects[10].CompleteByteFromSlot3F8=1;w.Objects[10].QuantityFromSlot618=int.MaxValue;w.ReagentIds.Add("records/a.dbr",11);w.Objects.Add(11,new ItemObject{Kind=ItemObjectKind.Item,QuantityFromSlot618=1});Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Count==int.MinValue,"signed sum wraps 32 bits");Is(v1.Evaluate(player).Value==false,"negative wrapped result signed comparison");
  Is(v1.Evaluate(new World()).Status=="Unsupported","unresolved main player");w.ReagentIndexComplete=false;w.ReagentIds.Clear();Is(ItemCountQuery.CountForHasItem(w,"records/a.dbr",true).Status=="Unsupported","unknown material index");
  Console.WriteLine("{\"status\":\"passed\",\"fixed_assertions\":"+n+"}");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
